select jsonb_build_object('native_schema_present',to_regnamespace('accommodation_property_private') is not null,'account_contract_present',to_regprocedure('public.account_features_allowed()') is not null,'storage_objects_rls',(select relrowsecurity from pg_class where oid='storage.objects'::regclass),'storage_buckets_rls',(select relrowsecurity from pg_class where oid='storage.buckets'::regclass),'native_bucket',(select jsonb_build_object('id',id,'public',public) from storage.buckets where id='accommodation-media'),'native_storage_objects',(select count(*) from storage.objects where bucket_id='accommodation-media'),'bucket_policies',(select coalesce(jsonb_agg(jsonb_build_object('name',policyname,'roles',roles,'cmd',cmd,'permissive',permissive)),'[]') from pg_policies where schemaname='storage' and tablename='buckets'),'temporary_hold',(select count(*) from pg_policies where policyname='native_deployment_bucket_hold')) as native_preflight;
